import { forwardRef, type ComponentPropsWithoutRef } from 'react'

type TextFieldProps = ComponentPropsWithoutRef<'input'> & { label: string }

export const TextField = forwardRef<HTMLInputElement, TextFieldProps>(
  function TextField({ label, ...props }, ref) {
    return (
      <label>
        {label}
        <input ref={ref} {...props} />
      </label>
    )
  },
)

import { useRef } from 'react'
import { TextField } from './TextField'

export function LoginForm() {
  const emailRef = useRef<HTMLInputElement>(null)
  const focusTimer = useRef<number>()

  function focusEmailSoon() {
    window.clearTimeout(focusTimer.current)
    focusTimer.current = window.setTimeout(() => emailRef.current?.focus(), 100)
  }

  return (
    <form>
      <TextField label="Email" ref={emailRef} type="email" name="email" />
      <button type="button" onClick={focusEmailSoon}>Change email</button>
      <button type="submit">Sign in</button>
    </form>
  )
}

